mapper.select:
SELECT C.* FROM (SELECT ROWNUM AS num, B.* FROM (SELECT COUNT(*) OVER() AS task_counts, A.* FROM (SELECT CONNECT_BY_ROOT(t.created_at) AS created_at, CONNECT_BY_ROOT(t.assignee_user_id) AS assignee_user_id, t.title, t.content, t.task_id, t.parent_task_id, LEVEL, u.user_name, c.code_name, t.progress_rate, t.start_date, t.due_date, p.project_name, p.project_id, p.parent_project_id, t2.type_name, t3.status_name, t3.task_status_id FROM tasks t JOIN projects p ON t.project_id = p.project_id JOIN task_types t2 ON t.task_type_id = t2.task_type_id JOIN task_statuses t3 ON t.task_status_id = t3.task_status_id JOIN common_code c ON t.priority_code = c.code_value LEFT JOIN users u ON t.assignee_user_id = u.user_id WHERE (p.project_id=#{projectId} OR p.parent_project_id = #{projectId}) AND t.is_deleted = 'Q2'
AND t.task_id = #{taskId}
AND t.assignee_user_id = #{assigneeUserId}
AND t.task_type_id = #{taskTypeId}
AND t.task_status_id = #{taskStatusId}
AND t.start_date >= #{startDate}
AND t.due_date <= #{endDate}
AND t.priority_code = #{priorityCode}
AND t.project_id = #{parentProjectId}
AND t.title LIKE '%' || #{search} || '%'
START WITH t.parent_task_id IS NULL CONNECT BY PRIOR t.task_id = t.parent_task_id ORDER SIBLINGS BY t.assignee_user_id DESC, t.created_at DESC) A)B WHERE ROWNUM BETWEEN 1 AND #{endNum})C WHERE C.num >= #{startNum}

